package com.billingcopilot.service;
import com.billingcopilot.model.BillingModels.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.List; import static org.junit.jupiter.api.Assertions.*;
class ReconciliationServiceTest {
 private final ReconciliationService service=new ReconciliationService(); private static BigDecimal bd(String x){return new BigDecimal(x);}
 @Test void detectsThreeCoreChecks(){var result=service.audit(new AuditRequest(List.of(new BillingRule("Salt application",bd("130"),"application"),new BillingRule("Emergency work",bd("165"),"hour"),new BillingRule("Pressure washing",bd("250"),"service")),List.of(new WorkItem("Salt application",bd("7")),new WorkItem("Emergency work",bd("3")),new WorkItem("Pressure washing",bd("1"))),List.of(new InvoiceItem("Salt application",bd("6"),bd("130")),new InvoiceItem("Emergency work",bd("3"),bd("150"))))); assertEquals(3,result.discrepancies().size()); assertEquals(0,bd("425.00").compareTo(result.totalPotentialImpact()));}
 @Test void cleanInvoiceProducesNoAlerts(){var r=service.audit(new AuditRequest(List.of(new BillingRule("Snow push",bd("450"),"push")),List.of(new WorkItem("Snow push",bd("2"))),List.of(new InvoiceItem("Snow push",bd("2"),bd("450")))));assertTrue(r.discrepancies().isEmpty());assertEquals(0,bd("0.00").compareTo(r.totalPotentialImpact()));}
 @Test void normalizesPunctuationAndCase(){var r=service.audit(new AuditRequest(List.of(new BillingRule("Emergency Clean-Up",bd("165"),"hour")),List.of(new WorkItem(" emergency clean up ",bd("2"))),List.of(new InvoiceItem("EMERGENCY CLEAN UP",bd("2"),bd("165")))));assertTrue(r.discrepancies().isEmpty());}
 @Test void aggregatesDuplicateInvoiceLinesBeforeComparingQuantity(){var r=service.audit(new AuditRequest(List.of(new BillingRule("Salt",bd("100"),"application")),List.of(new WorkItem("Salt",bd("4"))),List.of(new InvoiceItem("Salt",bd("2"),bd("100")),new InvoiceItem("Salt",bd("2"),bd("100")))));assertTrue(r.discrepancies().isEmpty());}
 @Test void flagsOverbillingQuantityForHumanReview(){var r=service.audit(new AuditRequest(List.of(new BillingRule("Salt",bd("100"),"application")),List.of(new WorkItem("Salt",bd("3"))),List.of(new InvoiceItem("Salt",bd("4"),bd("100")))));assertEquals("QUANTITY_MISMATCH",r.discrepancies().get(0).type());assertEquals(0,bd("100.00").compareTo(r.totalPotentialImpact()));}
 @Test void missingRuleStillFlagsMissingItemWithUnknownDollarImpact(){var r=service.audit(new AuditRequest(List.of(),List.of(new WorkItem("Special cleanup",bd("1"))),List.of()));assertEquals("MISSING_ITEM",r.discrepancies().get(0).type());assertEquals(0,bd("0.00").compareTo(r.totalPotentialImpact()));}
}
